// Reconcile plan + open reqs + hires by (team, level).
// Returns a structured table the narrative composer formats.
const fs = require('fs');
const yaml = require('js-yaml');

const MAPPING_PATH = $env.TEAM_MAPPING_PATH || '/data/team_mapping.yml';
let mapping;
try {
  mapping = yaml.load(fs.readFileSync(MAPPING_PATH, 'utf8'));
} catch (e) {
  return [{ json: { status: 'halted', reason: 'team_mapping_load_failed', error: e.message } }];
}

const plan = $('Fetch Plan').all().map(r => r.json);
const reqs = ($('Fetch Open Reqs (Ashby)').first().json.results?.jobs || []);
const hires = ($('Fetch Hires (HRIS)').first().json.employees || []);

// Plan-source freshness check.
const planLastUpdated = plan.length ? new Date(Math.max(...plan.map(p => new Date(p.last_updated_at).getTime()))) : null;
const planAgeDays = planLastUpdated ? Math.floor((Date.now() - planLastUpdated.getTime()) / 86400000) : null;
const planStale = planAgeDays !== null && planAgeDays > 14;

// Build cells keyed by team/level. Map cross-system team names through the mapping file.
const cells = new Map();
const key = (team, level) => `${team}::${level}`;
const getCell = (team, level) => {
  const k = key(team, level);
  if (!cells.has(k)) cells.set(k, { team, level, plan: 0, open_reqs: 0, hires: 0, conversions: 0, off_cycle: 0, anomalies: [] });
  return cells.get(k);
};

const mapTeam = (raw, source) => {
  const m = (mapping.teams || {})[raw];
  return m ? m.canonical : null;
};

for (const p of plan) {
  const t = mapTeam(p.team, 'plan');
  if (!t) { getCell(p.team, p.level).anomalies.push(`unmapped_plan_team:${p.team}`); continue; }
  const c = getCell(t, p.level);
  c.plan += p.count;
}

for (const r of reqs) {
  const t = mapTeam(r.team?.name || r.department || '', 'ashby');
  const level = r.customFields?.level || 'unknown';
  if (!t) { getCell(r.team?.name || 'unknown', level).anomalies.push(`unmapped_ashby_team:${r.team?.name}`); continue; }
  const c = getCell(t, level);
  c.open_reqs += 1;
}

const quarterStart = new Date(new Date().getFullYear(), Math.floor(new Date().getMonth() / 3) * 3, 1);
for (const h of hires) {
  const t = mapTeam(h.team, 'hris');
  const level = h.level || 'unknown';
  if (!t) { getCell(h.team || 'unknown', level).anomalies.push(`unmapped_hris_team:${h.team}`); continue; }
  const c = getCell(t, level);
  if (h.employmentType !== 'fte') {
    if (h.priorEmploymentType === 'contractor') c.conversions += 1;
    continue;
  }
  if (new Date(h.startDate) < quarterStart) c.off_cycle += 1;
  c.hires += 1;
}

// Compute variance per cell.
const rows = [];
for (const c of cells.values()) {
  const variance = c.plan - c.hires - c.open_reqs;
  rows.push({ ...c, variance, drift_warning: Math.abs(variance) > 3 });
}

// Anomaly cells: open reqs with no plan entry, hires with no plan entry.
const anomalyRows = rows.filter(r => r.anomalies.length > 0 || (r.open_reqs > 0 && r.plan === 0) || (r.hires > 0 && r.plan === 0));

return [{
  json: {
    quarter: `Q${Math.floor(new Date().getMonth() / 3) + 1}-${new Date().getFullYear()}`,
    plan_stale: planStale,
    plan_age_days: planAgeDays,
    rows,
    anomaly_rows: anomalyRows,
    totals: {
      plan: rows.reduce((s, r) => s + r.plan, 0),
      hires: rows.reduce((s, r) => s + r.hires, 0),
      open_reqs: rows.reduce((s, r) => s + r.open_reqs, 0),
      conversions: rows.reduce((s, r) => s + r.conversions, 0),
      off_cycle: rows.reduce((s, r) => s + r.off_cycle, 0),
    }
  }
}];

