// Split the LLM response into per-team posts and the aggregate post.
const llmResp = $input.first().json;
const recon = $('Reconcile').item.json;
const text = llmResp.content?.[0]?.text || '';

// Expect the LLM to return JSON with per_team and aggregate keys.
let parsed;
try {
  parsed = JSON.parse(text.match(/\{[\s\S]*\}/)[0]);
} catch (e) {
  parsed = { aggregate: text, per_team: {} };
}

const staleHeader = recon.plan_stale ? `\n\n:warning: Plan last updated ${recon.plan_age_days} days ago — variance may reflect plan staleness, not actual gap.` : '';

const posts = [];

// Per-team posts to per-team channels.
for (const row of recon.rows) {
  const teamSummary = parsed.per_team?.[row.team] || `${row.team} ${row.level}: plan ${row.plan}, hires ${row.hires}, open ${row.open_reqs}, variance ${row.variance}.`;
  posts.push({
    json: {
      type: 'per_team',
      channel: `#hiring-${row.team.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
      text: `*Headcount — ${recon.quarter} — week of ${new Date().toISOString().slice(0, 10)}*\n${teamSummary}${staleHeader}`,
    }
  });
}

// Aggregate post to leadership channel.
posts.push({
  json: {
    type: 'aggregate',
    channel: '#recruiting-leadership',
    text: `*${recon.quarter} headcount aggregate — week of ${new Date().toISOString().slice(0, 10)}*\n\nPlan: ${recon.totals.plan} · Hires: ${recon.totals.hires} · Open reqs: ${recon.totals.open_reqs} · Conversions: ${recon.totals.conversions} · Off-cycle: ${recon.totals.off_cycle}\n\n${parsed.aggregate || 'See per-team channels for breakdowns.'}\n\nAnomaly cells: ${recon.anomaly_rows.length}.${staleHeader}`,
  }
});

return posts;
